---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Code viewer: Code the agent wrote, with line notes you can ask about.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change code-viewer.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './code-viewer.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="code-viewer" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="cvx panel" data-reveal="flat">
  <div class="cvx-h"><div class="cvx-tabs" role="tablist"></div><span class="cvx-meta num"></span><button class="ib cvx-cp" aria-label="Copy file" data-tip="Copy"><svg class="i s"><use href="#i-copy"/></svg></button></div>
  <div class="cvx-body"><pre class="cvx-code"></pre></div>
</div>
  </Fragment></div>
</div>
<script>
  import './code-viewer.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Code viewer ---------- */
.cvx{overflow:hidden;display:flex;flex-direction:column}
.cvx-h{display:flex;align-items:center;gap:2px;height:44px;padding:0 var(--dm-s-2);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.cvx-tabs{display:flex;gap:2px;flex:1;min-width:0;overflow-x:auto}
.cvx-tab{display:flex;align-items:center;height:28px;padding:0 10px;border-radius:var(--dm-r-sm);font-size:12px;font-family:var(--dm-mono);color:var(--dm-muted);transition:color .2s,background .2s;white-space:nowrap}
@media (hover:hover) and (pointer:fine){.cvx-tab:hover{color:var(--dm-fg)}}
/* the tabs scroll sideways, which would cut an outside ring: theirs is drawn inside */
.cvx-tab:focus-visible{outline-offset:-2px}
.cvx-tab.on{background:var(--dm-surface);color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent)}
.cvx-meta{margin-left:auto;padding-right:2px;font-size:12px;color:var(--dm-muted);white-space:nowrap}
.cvx-meta b{font-weight:500;color:var(--dm-ok)}
.cvx-body{overflow-x:auto;min-height:232px}
.cvx-code{margin:0;padding:var(--dm-s-2) 0;font-family:var(--dm-mono);font-size:12px;line-height:1.8}
.cvx-l{display:flex;padding-right:var(--dm-s-4);cursor:pointer;transition:background .2s}
@media (hover:hover) and (pointer:fine){.cvx-l:hover{background:var(--dm-row)}}
/* a line that takes the focus fills the scrolling code, which would cut an outside ring: its ring is drawn inside */
.cvx-l:focus-visible{outline-offset:-2px}
.cvx-l.new{background:color-mix(in srgb,var(--dm-ok) 6%,transparent)}
.cvx-l.on{background:var(--dm-sel)}
@media (hover:hover) and (pointer:fine){.cvx-l.on:hover{background:var(--dm-sel)}}
.cvx-l .n{width:42px;text-align:right;padding-right:var(--dm-s-4);color:var(--dm-muted);user-select:none;flex:none;transition:color .2s}
.cvx-l.new .n{color:var(--dm-ok)}
.cvx-l.on .n{color:var(--dm-accent-fg,var(--dm-accent))}
.cvx-l .c{white-space:pre}
/* one cool family for the syntax (owner, 4 Nov: the warm and cool mix clashed): violet keywords, blue functions, teal
   components, green strings; attributes and the rest stay in the text greys */
.cvx-code .k{color:var(--dm-pl)}.cvx-code .s{color:var(--dm-pm)}.cvx-code .f{color:var(--dm-pb)}.cvx-code .cm{color:var(--dm-muted);font-style:italic}.cvx-code .tg{color:var(--dm-pt)}.cvx-code .at{color:var(--dm-fg2)}
/* the agent's note belongs to the line it explains (owner, 4 Nov: no grey box): it carries on in that line's tint, aligned
   with the code, like an inline review comment */
.cvx-note{margin:0;padding:var(--dm-s-1) var(--dm-s-4) var(--dm-s-2) 42px;background:var(--dm-sel);font-family:var(--dm-sans);font-size:12.5px;line-height:1.5;white-space:normal;color:var(--dm-fg2);display:flex;gap:var(--dm-s-2)}
.cvx-note>svg{color:var(--dm-accent-fg,var(--dm-accent));flex:none;margin-top:3px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, copied, html, stagger, swap } from '../core/core.js';
DM.def('code-viewer', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{copy}', I('copy'));
  const F = [
    { n:'PlanCard.tsx', t:'re', src:[
      ['<k>import</k> { Button } <k>from</k> <s>"@/ui/button"</s>;',0],
      ['',0],
      ['<k>export function</k> <f>PlanCard</f>({ plan }) {',0],
      ['  <cm>// One CTA per card, annual price first</cm>',1,'The agent removed the second link here. The design review said two CTAs split attention.'],
      ['  <k>return</k> (',0],
      ['    <tg>&lt;Card</tg> <at>padding</at>=<s>"lg"</s><tg>&gt;</tg>',0],
      ['      <tg>&lt;Price</tg> <at>value</at>={plan.annual} <at>was</at>={plan.monthly} <tg>/&gt;</tg>',1,'Shows the monthly price crossed out next to the annual one. This is the change behind the 18% lift.'],
      ['      <tg>&lt;Button</tg> <at>variant</at>=<s>"primary"</s><tg>&gt;</tg>{plan.cta}<tg>&lt;/Button&gt;</tg>',1,'Swapped the custom button for the shared one, so it picks up the library tokens.'],
      ['    <tg>&lt;/Card&gt;</tg>',0],
      ['  );',0],
      ['}',0]
    ]},
    { n:'tokens.css', t:'', src:[
      ['<f>:root</f> {',0],
      ['  --text-muted: <s>#5b6472</s>;',1,'Was #c9cfd8. Contrast on white goes from 2.1 to 5.9, which passes AA.'],
      ['  --radius-card: <s>16px</s>;',0],
      ['  --space-card: <s>24px</s>;',1,'Matched to the 4px grid. Was 18px.'],
      ['}',0]
    ]}
  ];
  const tabs = $('.cvx-tabs', r), code = $('.cvx-code', r), meta = $('.cvx-meta', r);
  tabs.innerHTML = F.map((f, i) => `<button class="cvx-tab" role="tab" data-i="${i}">${f.n}</button>`).join('');
  const hl = s => s.replace(/<(k|s|f|cm|tg|at)>/g, '<span class="$1">').replace(/<\/(k|s|f|cm|tg|at)>/g, '</span>');
  let cur = 0;
  function show(i){
    cur = i; $$('.cvx-tab', tabs).forEach((t, j) => { t.classList.toggle('on', j === i); t.setAttribute('aria-selected', j === i); });
    code.innerHTML = F[i].src.map((l, k) => `<div class="cvx-l${l[1] ? ' new' : ''}" data-k="${k}" role="button" tabindex="0" aria-expanded="false"><span class="n">${k + 1}</span><span class="c">${hl(l[0]) || ' '}</span></div>`).join('');
    stagger($$('.cvx-l', code), 18); meta.innerHTML = `<b>+${F[i].src.filter(l => l[1]).length}</b> changed`;
    // each line is a button, as in React: Enter or Space asks about it too
    $$('.cvx-l', code).forEach(el => { el.onclick = () => ask(el); el.onkeydown = e => { if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); ask(el); } }; });
  }
  // a note opens and closes its own height, so the code around it moves smoothly
  const fold = (n, open) => { const cs = getComputedStyle(n), ease = getComputedStyle(r).getPropertyValue('--dm-ease').trim() || 'ease';
    const full = { height:cs.height, marginTop:cs.marginTop, marginBottom:cs.marginBottom, paddingTop:cs.paddingTop, paddingBottom:cs.paddingBottom, opacity:1, overflow:'hidden' };
    const none = { height:'0px', marginTop:'0px', marginBottom:'0px', paddingTop:'0px', paddingBottom:'0px', opacity:0, overflow:'hidden' };
    return n.animate(open ? [none, full] : [full, none], { duration:REDUCE ? 1 : 420, easing:ease }); };
  function ask(el){
    const k = +el.dataset.k, l = F[cur].src[k], open = el.classList.contains('on');
    $$('.cvx-note:not(.going)', code).forEach(n => { n.classList.add('going'); fold(n, false).onfinish = () => n.remove(); }); $$('.cvx-l', code).forEach(x => { x.classList.remove('on'); x.setAttribute('aria-expanded', 'false'); });
    if (open) return;
    el.classList.add('on'); el.setAttribute('aria-expanded', 'true');
    const note = html(`<div class="cvx-note">${I('spark','xs')}<span><span class="shim">Reading the line</span></span></div>`); el.after(note); fold(note, true);
    c.later(600, () => swap($('span', note), l[2] || 'Unchanged. The agent kept this line as it was.'));
  }
  $$('.cvx-tab', tabs).forEach(t => t.onclick = () => show(+t.dataset.i));
  const cp = $('.cvx-cp', r);
  cp.onclick = () => { const txt = F[cur].src.map(l => l[0].replace(/<[^>]+>/g, '').replace(/&lt;/g,'<').replace(/&gt;/g,'>')).join('\n'); copied(cp, txt); };
  show(0);
  // the preview asks about one line on its own, unless you take over first
  c.auto(1200, () => { if (!$('.cvx-note', code)) ask($$('.cvx-l', code)[6]); });
});
